import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Module 8 · Event tickets","description":"","frontmatter":{},"headers":[],"relativePath":"modules/08-event-tickets.md","filePath":"modules/08-event-tickets.md","lastUpdated":1790431304000}'),i={name:"modules/08-event-tickets.md"};function r(o,e,l,d,h,c){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="module-8-·-event-tickets" tabindex="-1">Module 8 · Event tickets <a class="header-anchor" href="#module-8-·-event-tickets" aria-label="Permalink to &quot;Module 8 · Event tickets&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Contract</strong></td><td><code>EventTickets.sol</code></td></tr><tr><td><strong>Stop</strong></td><td>College</td></tr><tr><td><strong>Standard</strong></td><td>ERC-1155 (multi-token)</td></tr><tr><td><strong>Stamp</strong></td><td>Module 8</td></tr></tbody></table><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>Tickets have two failure modes that have never really been fixed: <strong>counterfeits</strong>, and a <strong>resale market</strong> the organiser neither sees nor controls. Paper and PDF tickets are copyable; platform tickets solve that by making the platform the only place a ticket can exist, which solves counterfeiting by creating a monopoly.</p><p>There is also a boring engineering problem underneath. A university runs dozens of events a year. Deploying a separate contract per event is expensive, slow, and leaves you with dozens of addresses to track.</p><h2 id="the-idea" tabindex="-1">The idea <a class="header-anchor" href="#the-idea" aria-label="Permalink to &quot;The idea&quot;">​</a></h2><p><strong>ERC-1155</strong>: one contract holding many token types, each with its own id, supply and balance. One deployment covers every event the college will ever run. Ticket 1 is the Harvest Festival, ticket 2 the guest lecture, and a holder&#39;s balance of each is just a number.</p><p>Tickets are ordinary transferable tokens — deliberately the opposite rule to module 2&#39;s Passport, and a good pair to think about together.</p><h2 id="key-terms" tabindex="-1">Key terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key terms&quot;">​</a></h2><p><strong>ERC-1155.</strong> A standard for many token types in one contract. Balances are <code>balanceOf(account, id)</code> rather than <code>balanceOf(account)</code>, and it supports batch operations. Designed for games, where one contract might hold a thousand item types.</p><p><strong>Fungible within a type.</strong> Two tickets to the same event are interchangeable, like ERC-20. Tickets to different events are not, like ERC-721. ERC-1155 gives you both at once, which is exactly what a ticket is.</p><p><strong>Burning to redeem.</strong> Using a ticket destroys it. Destruction is how you prevent reuse, and it is cheaper and clearer than a &quot;used&quot; flag on every ticket.</p><p><strong>Pull payments again.</strong> Refunds and proceeds are withdrawn, not pushed — the same reasoning as module 6.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> EventInfo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> organiser;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    uint256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> price;      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// TVD per ticket</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    uint64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> startsAt;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    uint32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> capacity;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    uint32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sold;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    uint32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> redeemed;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    bool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cancelled;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> name;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Function</th><th>Who</th><th>What</th></tr></thead><tbody><tr><td><code>createEvent(name, price, capacity, startsAt)</code></td><td>any resident</td><td>New ticket type</td></tr><tr><td><code>buy(id, quantity)</code></td><td>anyone</td><td>Mints tickets, takes TVD</td></tr><tr><td><code>redeem(id, quantity)</code></td><td>the holder</td><td>Burns them at the door</td></tr><tr><td><code>cancel(id)</code></td><td>the organiser</td><td>Before it starts; enables refunds</td></tr><tr><td><code>refund(id)</code></td><td>ticket holders</td><td>Only for a cancelled event</td></tr><tr><td><code>withdrawProceeds(id)</code></td><td>the organiser</td><td>Only after it has started</td></tr><tr><td><code>uri(id)</code></td><td>anyone</td><td>On-chain JSON metadata</td></tr></tbody></table><p>Two timing rules carry most of the safety:</p><ul><li><strong>Tickets cannot be bought after the event starts</strong> — <code>EventStarted()</code>.</li><li><strong>Proceeds cannot be withdrawn before it starts</strong> — <code>EventNotStarted()</code>.</li></ul><p>Together they mean an organiser cannot take the money and cancel. Until the event begins, every ticket&#39;s money is still in the contract, so a cancellation can always fund refunds in full.</p><p>That is a small amount of code doing a lot of work, and it is worth pausing on: the protection comes from <em>sequencing</em>, not from a guarantee fund or a trusted escrow agent.</p><h2 id="the-detail-that-matters" tabindex="-1">The detail that matters <a class="header-anchor" href="#the-detail-that-matters" aria-label="Permalink to &quot;The detail that matters&quot;">​</a></h2><p><strong>Redemption burns.</strong></p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">_burn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, id, quantity);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e.redeemed </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> quantity;</span></span></code></pre></div><p>A ticket that has been used no longer exists. Compare with a &quot;used&quot; boolean: that needs a per-ticket record, costs more gas, and leaves a token in the wallet that looks valid to any tool not checking the flag.</p><p><strong>Transferability is the design decision.</strong> Tickets move freely, so:</p><ul><li>A student who cannot attend can pass their ticket to a friend — no platform, no fee.</li><li>A tout can buy fifty and resell them at a markup.</li></ul><p>Both follow from the same property. The interesting question is not &quot;how do we stop touts&quot; but &quot;what are we willing to give up to stop them&quot;, because every mechanism costs the honest buyer something: non-transferable tickets (you cannot give yours away), price caps (a grey market forms), identity checks (queues and privacy).</p><p>Trustville chooses free transfer and says so plainly, rather than pretending the problem does not exist.</p><h2 id="walk-through-it" tabindex="-1">Walk through it <a class="header-anchor" href="#walk-through-it" aria-label="Permalink to &quot;Walk through it&quot;">​</a></h2><ol><li>Create an event with a small capacity, a price, and a start time a few minutes ahead.</li><li>From a second account, buy two tickets. Check <code>balanceOf(account, id)</code>.</li><li>Transfer one to a third student. It moves like any token.</li><li>Try to withdraw the proceeds now. <code>EventNotStarted</code>.</li><li>Redeem a ticket. The balance drops and the supply falls.</li><li>Redeem it again. There is nothing left to burn.</li><li>On another event, cancel it before it starts and take a refund.</li></ol><h2 id="what-actually-happened-on-chain" tabindex="-1">What actually happened on chain <a class="header-anchor" href="#what-actually-happened-on-chain" aria-label="Permalink to &quot;What actually happened on chain&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TransferSingle(operator, from: 0x0, to: buyer, id: 2, value: 2)   // ERC-1155 mint</span></span>
<span class="line"><span>TicketsBought(id: 2, buyer: 0x…, quantity: 2, cost: 20e18)</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>TransferSingle(operator, from: holder, to: 0x0, id: 2, value: 1)  // redeem = burn</span></span></code></pre></div><p>ERC-1155 uses one event shape for mint, transfer and burn, distinguished by whether <code>from</code> or <code>to</code> is the zero address. Reading balances from logs therefore means handling all three cases — which the labs will have you do.</p><h2 id="when-a-plain-database-is-better" tabindex="-1">When a plain database is better <a class="header-anchor" href="#when-a-plain-database-is-better" aria-label="Permalink to &quot;When a plain database is better&quot;">​</a></h2><p>For a university selling tickets to its own events: a database, every time. Cheaper, private, instantly refundable, and it can enforce &quot;one per student&quot; because it knows who students are.</p><p>ERC-1155 earns its place when tickets should be <strong>transferable without the issuer&#39;s involvement</strong>, when holders want custody rather than an account on a platform, or when the tickets need to work with other software — a wallet, a game, a contract that accepts them as proof of attendance.</p><h2 id="what-this-does-not-fix" tabindex="-1">What this does not fix <a class="header-anchor" href="#what-this-does-not-fix" aria-label="Permalink to &quot;What this does not fix&quot;">​</a></h2><ul><li><strong>Touting.</strong> Free transfer means resale.</li><li><strong>The door.</strong> Somebody must connect a wallet at the entrance; a burned ticket proves nothing about who is standing there.</li><li><strong>Sybil buying.</strong> One address, fifty tickets, or fifty addresses with one each.</li><li><strong>The chargeback problem.</strong> No mechanism exists for &quot;the event was terrible&quot;.</li></ul><h2 id="common-mistakes" tabindex="-1">Common mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common mistakes&quot;">​</a></h2><ul><li><strong>Letting the organiser withdraw before the event.</strong> Take the money, cancel, keep it.</li><li><strong>Refunds in a loop over holders.</strong> One reverting recipient freezes all refunds.</li><li><strong>Using ERC-721 per ticket.</strong> Works, costs far more, and gives you nothing for a fungible item.</li><li><strong>Forgetting capacity checks.</strong> Overselling is a contract bug, not a business decision.</li><li><strong>Assuming <code>balanceOf</code> has one argument.</strong> ERC-1155 takes an id too.</li></ul><h2 id="security-checklist" tabindex="-1">Security checklist <a class="header-anchor" href="#security-checklist" aria-label="Permalink to &quot;Security checklist&quot;">​</a></h2><ul><li>[ ] Can the organiser withdraw before the event starts?</li><li>[ ] Can tickets be bought after it starts? After cancellation?</li><li>[ ] Can a ticket be redeemed twice? Redeemed and then refunded?</li><li>[ ] Does <code>sold</code> ever exceed <code>capacity</code>?</li><li>[ ] After a cancellation, is the contract&#39;s balance always enough for every refund?</li><li>[ ] Can a holder refund tickets they already redeemed?</li></ul><h2 id="extend-it" tabindex="-1">Extend it <a class="header-anchor" href="#extend-it" aria-label="Permalink to &quot;Extend it&quot;">​</a></h2><ol><li>Add a resale cap: transfers must go through a function that limits the price. Find the hole — direct <code>safeTransferFrom</code> still works — and decide what you would really have to restrict.</li><li>Add tiered tickets (student, staff, public) as separate ids in the same event, and notice how little code that takes with ERC-1155.</li><li>Award a passport stamp for <em>attending</em>, so redemption leaves a permanent record. Then ask whether that is a nice feature or a surveillance one.</li></ol><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://eips.ethereum.org/EIPS/eip-1155" target="_blank" rel="noreferrer">ERC-1155</a></li><li><a href="https://docs.openzeppelin.com/contracts/5.x/erc1155" target="_blank" rel="noreferrer">OpenZeppelin ERC1155</a></li><li>Compare with ERC-721 and ERC-20, and be able to say when each is right.</li></ul><p><strong>Next:</strong> <a href="./09-property-deeds">Module 9 · Property deeds →</a></p>`,47)])])}const k=t(i,[["render",r]]);export{u as __pageData,k as default};
